/**
 * TRANSFÉRER LE CONTRÔLE D’UNE PRÉSENTATION
 *
 * Exécutez cette macro pendant une présentation synchronisée active.
 * Modifiez CONTROLLER avec le nom exact ou l’ID du nouveau contrôleur.
 * Le nouvel utilisateur doit être connecté.
 */

// ── CONFIGURATION À MODIFIER ──────────────────────────────────
const CONTROLLER = "REMPLACEZ_MOI"; // Exemple : "Alice"
// ──────────────────────────────────────────────────────────────

if (!game.user.isGM) return ui.notifications.error("Cette macro est réservée au MJ.");
const api = game.modules.get("retro-crt-terminal")?.api;
if (!api) return ui.notifications.error("Retro CRT Terminal n’est pas actif.");
if (!api.shared.state?.active) return ui.notifications.warn("Aucune présentation synchronisée n’est active.");
if (!CONTROLLER || CONTROLLER === "REMPLACEZ_MOI") {
  return ui.notifications.warn("Modifiez CONTROLLER dans la configuration de la macro.");
}

const controller = game.users.get(CONTROLLER) ?? game.users.find(user => user.name === CONTROLLER);
if (!controller) return ui.notifications.error(`Utilisateur introuvable : ${CONTROLLER}`);
if (!controller.active) return ui.notifications.error(`${controller.name} n’est pas connecté.`);

await api.shared.update({ controllerUserId: controller.id });
ui.notifications.info(`Contrôle transféré à ${controller.name}.`);
